(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["af"] = {"ui":{"skip":"Spring na die inhoud","back":"← Terug na AI-gile","lang.button":"Taal: {name}","lang.dialog":"Kies 'n taal","lang.search":"Soek tale","lang.none":"Geen taal pas nie","lang.notYet":"{name} is nog nie vertaal nie","theme.aria":"Wissel tussen lig en donker tema","theme.toLight":"Wissel na lig tema","theme.toDark":"Wissel na donker tema","words.underline":"Onderstreep hierdie woorde op die bladsy","words.underlineHelp":"Beweeg oor of tik op 'n gestippelde woord om te sien wat dit beteken.","index.title":"AI-gile: jou KI-ontwikkelaarspan, op een bord","index.description":"AI-gile is 'n kanban-bord vir KI-programmeerspanne. Hulle werk terwyl jy slaap; jy kry een kort hopie dinge om te besluit, te toets en te aanvaar.","hero.logoAlt":"AI-gile-bordikoon","hero.h1.html":"Jou KI-ontwikkelaarspan, op een&nbsp;bord.","hero.alpha":"🐣 Geslote pre-alfa","hero.alphaTitle":"Vroeg en onafgehandel: dankie dat jy dit probeer!","hero.lede":"Hulle bou terwyl jy slaap. Jy word wakker met een kort hopie: 'n paar vrae, 'n paar goed om te toets, een of twee pers diamante. Klik, aanvaar, terug na jou koffie.","dl.windows":"Windows-app","dl.browser":"Gebruik dit in jou blaaier","dl.soon":"Binnekort","dl.notify":"🔔 Laat weet my wanneer dit oopgaan","dl.notifySmall":"Alfa of beta","hero.secondary":"Agile, maar die span hoef nooit 'n stand-up-koffie te drink nie. (Hulle hou tog stand-ups.)","pitch.h2":"AI-gile in soveel woorde as jy wil","pitch.lede":"Kies 'n lengte, van een woord tot 144. Elke lengte is sy eie beskrywing, vir daardie grootte geskryf. Sleep die skuifbalk of gebruik die pyltjiesleutels.","pitch.rangeLabel":"Lengte in woorde","pitch.dice":"🎲 nog 'n weergawe","pitch.words.one":"{n} woord","pitch.words.other":"{n} woorde","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karakters","count.line.html.one":"{n} kaart op die bord op die oomblik","count.line.html.other":"{n} kaarte op die bord op die oomblik","features.aria":"Wat dit doen","f.pile.h":"Een hopie vir jou","f.pile.html":"<b>Vir jou</b> hou alles wat op jou wag, oor elke projek heen: vrae, goed om te toets, take wat net 'n mens kan doen. Jou tou sê wat volgende is en hoe lank dit neem.","f.sleep.h":"Spanne wat werk terwyl jy slaap","f.sleep.p":"Elke projek het 'n leier en 'n span KI-agente. Lewer kommentaar op 'n kaart en die span word wakker, doen die werk, en gee dit terug met stappe wat 'n moeë mens kan volg.","f.tester.h":"'n KI-toetser kyk eerste","f.tester.p":"Voordat enigiets by jou uitkom, volg 'n toetser die stappe in 'n kopie van die app en wys wat hy gesien het, met 'n skermkiekie. Blaai deur die geslaagdes en aanvaar met een klik.","f.proof.h":"Bewys, nie beloftes nie","f.proof.p":"Elke oorhandiging wys wat verander het: die lêers, die diff, die skermkiekies. Jy hoef nie elke app oop te maak om te sien of dit klaar is nie.","f.chat.h":"Gesels met jou leiers","f.chat.p":"'n Discord-agtige balk: een ikoon per projek, pers diamante vir wat jou nodig het. Stuur 'n leier 'n idee; hy maak dit kaarte en 'n plan, met 'n ✅ Gaan-knoppie.","f.tidy.h":"Hou homself netjies","f.tidy.p":"Verwante kaarte word een, deurmekaar titels word reggemaak, en 'n token-kontrole hou die kode skraal. Minder om tussen te wissel, minder om aan te dink.","f.private.h":"Joune, op jou rekenaar","f.private.li1":"Die bord loop op jou eie masjien en antwoord net vir jou.","f.private.li2":"Private DM's tussen mense is end-tot-end-geënkripteer.","f.private.li3":"Geen rekeninge, geen snuffelaars, geen koekies.","f.lang.h":"In jou taal","f.lang.p":"Meer as 120 tale, van Nederlands, Wallies en Japannees tot seerower, Yoda en Klingon, met 'n vinnige wissel terug na Engels vir die ontwikkelaarswoorde.","tl.aria":"Tydlyn van die eerste gesprek tot die padkaart","tl.h2":"Van die eerste gesels tot wat volgende kom","tl.lede":"Regte datums en tye, in jou eie tydsone. Ná vandag is dit die plan, sonder beloofde datums.","tl.today":"Vandag","tl.planned":"beplan","tl.cards.one":"{n} kaart","tl.cards.other":"{n} kaarte","join.h2":"Doen saam","join.lede":"AI-gile word gebou deur 'n klein mens en 'n groot klomp geduldige agente. Dit is vir eers privaat, in 'n geslote alfa met vriende. Wil jy 'n kans hê wanneer dit oopgaan?","join.btn":"Teken belangstelling in","join.small":"Ons stuur jou 'n e-pos, niks anders nie","footer.tag":"AI-gile. Geen snuffelaars, geen koekies, geen stand-up-koffie.","footer.licence":"Besigheidslisensie","footer.status":"Status","footer.privacy":"Wat ons hou","form.sending":"Stuur tans…","form.failed":"Dit het nie gewerk nie: probeer later weer.","form.offline":"Kon nie AI-gile bereik nie: probeer later weer.","form.keep":"Ons gebruik dit net om jou te antwoord, en vee dit dan uit. Geen snuffelaars, geen koekies.","form.keepLink":"Wat ons hou","interest.title":"AI-gile: laat weet my wanneer die alfa oopgaan","interest.description":"Los jou e-pos om te hoor wanneer AI-gile se geslote alfa of beta oopgaan.","interest.h1":"🔔 Laat weet my wanneer dit oopgaan","interest.lede":"AI-gile is in geslote pre-alfa. Los jou e-pos en ons skryf een keer, wanneer daar 'n plek vir jou is.","interest.email":"Jou e-pos","interest.which":"Watter toets?","interest.alpha":"Geslote alfa: vroeg, rof, baie veranderinge","interest.beta":"Beta: bestendiger, later","interest.both":"Enige een, wat ook al eerste kom","interest.submit":"Sit my op die lys","interest.thanks":"Dankie! Jy is op die lys.","licence.title":"AI-gile: besigheidslisensie","licence.description":"Gebruik jy AI-gile in jou besigheid? Doen aansoek om 'n gratis besigheidslisensie.","licence.h1":"📜 Besigheidslisensie","licence.lede":"Gebruik jy AI-gile by die werk? Vertel ons wie jy is en wat jy doen. As dit 'n bietjie goed doen, is die lisensie gratis.","licence.company":"Maatskappy","licence.website":"Webwerf","licence.what":"Wat jy doen","licence.how":"Hoe dit die wêreld help","licence.email":"E-pos","licence.submit":"Doen aansoek","licence.thanks":"Dankie! Ons antwoord per e-pos.","status.title":"AI-gile-status","status.h1":"AI-gile-status","status.quiet":"Alles rustig","status.intro":"Werk AI-gile nou? Hierdie bladsy kyk elke 5 minute na die webwerf, borddeling, oproepe en die aflaai.","status.up":"Werk (het in {ms} ms geantwoord)","status.slow":"Het nie op die laaste kontrole geantwoord nie, probeer weer","status.down":"Af: het nie op die laaste twee kontroles geantwoord nie","status.svc.web":"Webwerf","status.svc.web.offers":"Hierdie werf: wat AI-gile is, en die belangstellingsvorm","status.svc.boards":"Borddeling","status.svc.boards.offers":"Openbare borde, boodskappe tussen vriende en uitnodigings","status.svc.calls":"Oproepe","status.svc.calls.offers":"Stem, video en skermdeling in AI-gile","status.svc.download":"Aflaai","status.svc.download.offers":"Die Windows-installeerder en uitnodigingskakels","status.checking":"Kyk tans…","status.offline":"Kan die statusdiens nou nie bereik nie (probeer weer)","status.updated":"opgedateer {ago}","status.justNow":"nou net","status.min":"{n} min gelede","status.hours":"{n} u gelede","status.days":"{n} d gelede","privacy.title":"AI-gile: wat ons hou","privacy.h1":"Wat ons hou","privacy.lede":"Kort weergawe: net wat jy vir ons stuur, en nie vir lank nie.","privacy.only":"Net wat jy vir ons stuur: wat jy in 'n vorm intik, soos jou e-pos. Niks anders oor jou nie.","privacy.sealed":"Dit word verseël sodat ons bediener dit nie kan lees nie: in jou blaaier voordat dit vertrek (op 'n ouer blaaier, die oomblik wat dit aankom). Net ons eie bord kan dit oopmaak.","privacy.server":"Dit word van die bediener uitgevee sodra dit ons bord bereik. Enigiets wat ná 30 dae nog daar is, word in elk geval uitgevee.","privacy.board":"Ons hou dit net op ons bord totdat ons jou geantwoord het, en vee dit dan daar ook uit.","privacy.none":"Geen snuffelaars, geen koekies, geen analitika.","privacy.local":"Jou taal en lig- of donkerkeuse bly in jou eie blaaier. Dit word nooit na ons gestuur nie.","privacy.ask":"Wil jy hê dit moet gouer weg wees? Antwoord op ons e-pos en sê so.","live.h2":"Kyk hoe dit gebou word, regstreeks","live.caption":"Elke kaart is versteek: jy sien die vorm van die werk, nie die woorde nie.","live.watching.one":"regstreeks: {n} kyk","live.watching.other":"regstreeks: {n} kyk","live.last.now":"Laaste kaart pas verskuif","live.last.min.one":"Laaste kaart {n} min gelede verskuif","live.last.min.other":"Laaste kaart {n} min gelede verskuif","live.last.hour.one":"Laaste kaart {n} uur gelede verskuif","live.last.hour.other":"Laaste kaart {n} uur gelede verskuif","live.last.day.one":"Laaste kaart {n} dag gelede verskuif","live.last.day.other":"Laaste kaart {n} dae gelede verskuif","live.offline":"Die lewendige bord haal asem. Kom kyk gou weer.","live.cols":"Backlog|Om te doen|Besig|Span kontroleer|Vir jou om te toets|Vir die span|Klaar"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotte.","Uitbestee."]},{"n":2,"texts":["Robotte-kanban, gratis.","Agente, georganiseer.","Idees, gebou."]},{"n":3,"texts":["Kanban vir robotte.","Idees word funksies.","Gratis agent-kanban."]},{"n":5,"texts":["Kanban-bord wat agente bestuur.","Jy skryf kaarte. Agente bou.","Gratis, plaaslik, getoets, effens simpel."]},{"n":8,"texts":["'n Gratis kanban-bord waar KI-agente werk doen.","Skryf 'n idee. Agente bou dit. Jy aanvaar.","Agile vir een mens en baie geduldige robotte."]},{"n":13,"texts":["'n Kanban-bord op jou rekenaar waar KI-agente die kaarte optel en afhandel.","Skryf 'n idee. 'n Span agente bou dit. 'n Toetser kyk dit na.","Gratis, geen rekeninge, geen snuffelaars: 'n bord, 'n paar robotte, en jy aan die stuur."]},{"n":21,"texts":["AI-gile is 'n kanban-bord om saam met KI-programmeeragente te werk. Hulle tel die kaarte op; jy toets en aanvaar dit.","Elke projek kry 'n leier en 'n span KI-agente. Lewer kommentaar op enige kaart en die span gaan aan die werk.","'n Gratis, persoonlike taakbord wat op jou eie rekenaar loop. Die werkers is robotte. Die een wat ja sê, is jy."]},{"n":34,"texts":["Jy sit idees op 'n bord. 'n Span KI-agente maak daarvan werkende funksies, toets dit, en gee dit terug met stappe om te probeer. Niks tel as klaar totdat jy dit sê nie.","AI-gile is 'n tuisgemaakte kanban-bord wat Rich gebou het met baie hulp van die agente wat dit nou bestuur. Dit is gratis, loop op jou rekenaar, en word met vriende gedeel, nie verkoop nie.","Dink aan 'n gewone kanban-bord, met kolomme van Backlog tot Klaar, behalwe dat KI-agente die kaarte optel. Hulle rapporteer vordering, vra vrae as hulle vassit, en wag altyd vir jou duim in die lug."]},{"n":55,"texts":["AI-gile is 'n kanban-bord waar die span uit KI-agente bestaan. Elke projek het 'n leier wat die werk beplan en helpers wat dit bou. Wanneer 'n funksie gereed is, probeer 'n KI-toetser dit en neem 'n skermkiekie, dan beland dit in jou hopie. Aanvaar dit, of lewer kommentaar en hulle werk dit oor.","Dit het begin as een persoon se manier om baie KI-programmeersessies gelyktydig dop te hou, en het gegroei tot 'n regte bord. Dit loop op jou masjien, vra geen rekening nie, en het geen snuffelaars nie. Dit is gratis vir vriende en enigeen wat nuuskierig is. Dit is ook onafgehandel, so verwag rowwe kante en die af en toe verrassing.","Hier is die eerlike weergawe. Jy moet steeds die idees hê, en jy moet steeds die resultate nagaan. Wat AI-gile doen, is alles tussenin: dit hou die kaarte in orde, wek die regte agent wanneer jy kommentaar lewer, wys presies wat verander het, en hou alles in een kort hopie vir jou."]},{"n":89,"texts":["AI-gile is 'n gratis kanban-bord wat jy op jou eie rekenaar laat loop. In plaas van mense het elke projek 'n span KI-agente: 'n leier wat jou idees in kaarte en 'n plan omskep, en helpers wat die kaarte in volgorde van prioriteit optel. Wanneer iets gebou is, volg 'n KI-toetser die toetsstappe en wys jou wat hy gesien het. Dan wag dit in een hopie gemerk Vir jou. Jy aanvaar dit, of jy lewer kommentaar en die span probeer weer. Niks kom ooit by Klaar uit sonder jou nie.","Party funksies verwag jy dalk nie. 'n Nagwag hou die kolom Om te doen aangevul terwyl jy slaap, en kies kaarte wat nie 'n antwoord van jou nodig het nie. 'n Tokenteller wys hoeveel die agente vandag en hierdie week gebruik het, en Geen-Token-Modus sê vir hulle om op te hou spandeer. Jy kan vriende boodskappe stuur, en private boodskappe is end-tot-end-geënkripteer. Die bord praat sowat 120 tale, onder andere Nederlands, Vlaams, seerower en Klingon. Niks daarvan kos 'n sent nie, en niemand probeer dit ook vir jou verkoop nie.","AI-gile is 'n klein, persoonlike projek, nie 'n maatskappy nie. Rich wou na etlike KI-programmeerprojekte omsien sonder om elke app oop te maak om daarna te kyk, so hy en die agente het 'n bord daarvoor gebou, en toe die bord gebruik om die res van homself te bou. Dit is in geslote pre-alfa, wat beteken dit werk, meestal, vir 'n handjievol vriende. Daar is geen pryslys, geen nuusbrief en geen groeiplan nie. As dit nuttig klink, kan jy vra om dit te probeer wanneer dit 'n bietjie verder oopgaan."]},{"n":144,"texts":["AI-gile is 'n kanban-bord vir een mens en 'n klomp KI-agente. Dit loop op jou eie rekenaar en dit is heeltemal gratis. Jy voeg projekte by, en elke projek kry 'n leier en 'n klein span. Jy gesels met die leier, 'n bietjie soos op Discord, en beskryf 'n idee; die leier maak dit kaarte en 'n plan, en wag dan dat jy Gaan druk. Die span werk die kaarte in volgorde van prioriteit af, met 'n eenvoudige opdragreël wat vir taalmodelle gemaak is. Voordat enigiets na jou terugkom, volg 'n KI-toetser die stappe in 'n kopie van die app en heg 'n skermkiekie aan. Klaargemaakte werk beland in jou hopie met die veranderde lêers en die diff. Jy aanvaar dit, of jy los 'n kommentaar en die span word wakker en probeer weer. Net jy kan 'n kaart na Klaar skuif.","'n Dag met AI-gile, ongeveer. In die aand los jy 'n paar kommentare: hierdie knoppie is op die verkeerde plek, daardie lys moet gesorteer wees, kan ons 'n donker modus kry. Jy gaan slaap. Die agente lees die kommentare, maak die veranderinge, toets dit en gee dit aan jou terug. As Om te doen leegloop, vul die nagwag dit uit die backlog met kaarte wat geen antwoord van jou nodig het nie. In die oggend is daar een kort hopie: 'n paar vrae en 'n paar goed om te probeer, elk met stappe wat 'n slaperige mens kan volg en 'n skermkiekie wat wys dit werk. Jy klik deur, aanvaar die goeies en stuur die res terug. 'n Tokenteller wys wat alles gebruik het, en Geen-Token-Modus is daar vir maer weke. Dan eet jy ontbyt, waarmee die agente nog nie kan help nie.","Eerstens, wat AI-gile nie is nie. Dit is nie 'n begin-maatskappy nie, dit is nie te koop nie, en niemand versamel jou data nie. Dit is 'n gratis bord wat op jou rekenaar loop, sonder rekeninge, snuffelaars of koekies. Wat dit wel is: een netjiese plek om elke KI-programmeerprojek gelyktydig te sien, met 'n span agente wat die kaarte doen en jy wat die besluite neem. Dit voeg verwante kaarte saam, maak deurmekaar titels reg, en hou dop hoe skraal die kode bly. Dit praat sowat 120 tale, van Nederlands en Vlaams tot seerower en Klingon. Vriende kan mekaar boodskappe stuur, privaat en geënkripteer. Dit is gebou deur Rich en 'n groot klomp geduldige agente, meestal deur homself te gebruik. Dit is in geslote pre-alfa, so dit is op plekke rof. As dit na pret klink, vra mooi en jy kan dalk vroeg inkom."]}],"quips":{"1":"Een woord. Gewaagd. Dalk te gewaagd.","3":"Drie woorde. Reeds eerliker as die meeste produkbladsye.","8":"Agt woorde. Steeds korter as 'n stand-up.","21":"Die lengtes is storiepunte, terloops. Natuurlik is hulle.","55":"Vyf-en-vyftig woorde. Twee kaarte is klaar terwyl jy dit gelees het.","144":"Dis die lang een. Daar is geen 233 nie. Die agente is gaan slaap."}},"timeline":{"first-idea.name":"Die eerste idee","first-idea.line":"Die allereerste gesprek, voordat daar enige kode was.","first-board.name":"Eerste bord","first-board.line":"'n Bord wat sy eie bou naspoor: kaarte, kolomme, sleep-en-los, projekte.","team-roles.name":"Span en rolle","team-roles.line":"Agentprofiele, spansjablone, ruimtes en wie wat doen.","install.name":"Installeer en weergawes","install.line":"'n Zip wat 'n vriend kan installeer, selfopdatering, kanale en terugrol.","usage-saver.name":"Gebruiksbespaarder","usage-saver.line":"Meet wat lopies kos, hou die kode skraal, spaar jou limiet.","friends.name":"Vriende en deel","friends.line":"Private DM's, 'n versleutelde relay, uitnodigings, rolle en gedeelde projekte.","languages.name":"Tale","languages.line":"Elke skermteks in 'n taallêer, met Nederlands en Vlaams eerste.","ai-tester.name":"KI-toetser","ai-tester.line":"'n Toetser kyk elke oorhandiging eerste na en wys wat hy gesien het.","website.name":"Die webwerf","website.line":"aigile.lol, die teaser en hierdie tydlyn.","streaming.name":"Klets en stroming","streaming.line":"Discord, Twitch, OBS, stroomermodus, GIF's en emoji's.","no-ai.name":"Sonder-KI-uitgawe","no-ai.line":"'n Bord vir mense wat sonder KI programmeer, en openbare borde.","night-watch.name":"Nagwag","night-watch.line":"'n Wag en Scrum Master hou die spanne op koers terwyl jy slaap.","p-more.name":"Alles anders","p-more.line":"Kleiner idees wat nog op hul beurt wag.","p-android.name":"Foon en Android","p-android.line":"Bereik jou bord vanaf 'n foon, dan 'n eie Android-app.","p-release.name":"Alfa en verder","p-release.line":"Geslote alfa, die lewendige werf, dan beta.","p-languages.name":"Meer tale","p-languages.line":"Meer as honderd tale, en 'n onderdompelingsmodus vir leerders.","p-engines.name":"Meer KI-enjins","p-engines.line":"Kies Claude, Codex of Gemini per agent.","p-pro.name":"Professionele praktyk","p-pro.line":"Risikoetikette, samevoegpoorte, voorvalkaarte en leuningrelings.","p-self.name":"Na jou omsien","p-self.line":"Moeë-modus, selfsorg-herinnerings en 4:20.","p-servers.name":"Bedieners en skaal","p-servers.line":"Globale bedienerinstellings, rolle en beplanning vir groei.","p-livestream.name":"Stroom-ekstras","p-livestream.line":"Twitch-klets, eie emoji's en 'n openbare regstreekse blik."},"words":{"button":"📖 Ontwikkelaarswoorde","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Soek 'n woord…","none":"Geen woord stem daarmee ooreen nie.","close":"Maak toe","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Die projek se gids met kode en sy volle geskiedenis van commits, gewoonlik ook op GitHub gehou.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"'n Aparte werklyn in die kode, sodat veranderinge gemaak kan word sonder om aan die hoofweergawe te raak.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"'n Gestoorde kiekie van die kode, met 'n kort nota van wat verander het. Jy kan altyd na een teruggaan.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Gestoorde kiekies (commits) van hierdie rekenaar na GitHub stuur, sodat hulle 'n rugsteun het en gedeel word."},{"id":"merge","g":"build","word":"Merge","text":"Die veranderinge van 'n branch weer by die hoofweergawe voeg."},{"id":"pr","g":"build","word":"Pull request","text":"Vra dat 'n branch se veranderinge nagegaan en by die hoofweergawe saamgevoeg word.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Die kode opruim sonder om te verander wat dit doen: kleiner lêers, duideliker name, minder herhaling."},{"id":"bug","g":"build","word":"Bug","text":"Iets wat nie werk soos dit moet nie.","also":["bugs","fout","foute"]},{"id":"test","g":"build","word":"Toets","text":"'n Voltooide stuk werk uitprobeer om seker te maak dit doen wat gevra is, voordat jy dit aanvaar.","also":["toetse","test","tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"'n Nuwe weergawe aanlyn sit, byvoorbeeld op 'n bediener waar mense dit gebruik."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Idees en werk wat nog nie ingeskeduleer is nie. Daar word aan niks gewerk voordat dit na Om te doen skuif nie."},{"id":"sprint","g":"team","word":"Sprint","text":"'n Kort tydperk van werk (dikwels 'n week of twee) met 'n ooreengekome stel kaarte om klaar te maak.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"'n Vinnige inskakeling: wat elke spanlid gedoen het, wat hulle volgende doen, en wat hulle terughou.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"'n Bord met kolomme (Om te doen, Besig, Klaar) waar kaarte van links na regs skuif soos werk gebeur."},{"id":"wip","g":"team","word":"WIP-limiet","text":"Work in progress: die hoogste aantal kaarte wat 'n kolom mag hou, sodat die span dinge klaarmaak voor hulle meer begin.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"'n KI wat self aan 'n taak werk: lees die kode, maak veranderinge, voer kontroles uit, en rapporteer terug.","also":["agents","agente"]},{"id":"token","g":"team","word":"Token","text":"Die eenheid waarin KI-gebruik getel word: min of meer 'n paar letters teks gelees of geskryf. Minder tokens, meer van jou plan oor.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"'n Klein opdrag wat self op 'n bepaalde oomblik loop, bv. wanneer 'n KI-sessie begin, sodat die span jou kommentaar hoor.","also":["hooks"]}]}};
